  printing=await worker.new_page();await printing.set_content(await p.frames[-1].content());await printing.locator('.qr img').evaluate('(i)=>i.decode()');assert await printing.locator('.qr img').evaluate('(i)=>Math.abs(i.getBoundingClientRect().width-10*96/25.4)<1');await printing.add_script_tag(path='/workspace/SICIP/central/public/vendor/jsQR.js');folio=await printing.locator('.qr img').evaluate('''i=>{const c=document.createElement('canvas');c.width=i.naturalWidth;c.height=i.naturalHeight;const x=c.getContext('2d');x.drawImage(i,0,0);const d=x.getImageData(0,0,c.width,c.height);return jsQR(d.data,c.width,c.height).data;}''');pdf=await printing.pdf(prefer_css_page_size=True,print_background=True);doc=fitz.open(stream=pdf,filetype='pdf');assert len(doc)==1;assert doc[0].rect.width==612;txt=doc[0].get_text();assert '1A74-009-021' in txt and 'TESTUSER' in txt and 'PÉREZ' in txt and '05/01/2027' in txt;Path('/workspace/sicip-env/pecv-trabajador.pdf').write_bytes(pdf);doc[0].get_pixmap(matrix=fitz.Matrix(1.4,1.4)).save('/workspace/sicip-env/pecv-trabajador.png');await printing.close();await p.locator('.coverage-print-dialog [data-close]').click();data=await api('/api/vacaciones/mi-pecv',own=True);child=next(r for r in data['solicitudes'] if r['folio']==folio);assert child['estado']=='ENVIADA';original=await api('/api/vacaciones/registros/'+parent['uuid']);assert original['plan']==parent['plan'];print('Datos y firmas recuperados, solicitud enviada una sola vez, QR válido y formato Excel en una página carta.',flush=True)
