  await admin.grant_permissions(['camera']);await ap.evaluate("history.pushState({},'', '/recepciones');dispatchEvent(new PopStateEvent('popstate'))");await ap.locator('#sicip-recep-folio-input').wait_for(state='attached');await ap.evaluate("f=>{window.jsQR=()=>({data:f});window.__SICIP_RECEP_QR_SCAN__();}",folio);await ap.locator('[data-receive]').wait_for(timeout=20000);await ap.locator('#sicip-recep-folio-result').get_by_text('Matrícula TESTUSER',exact=False).wait_for();await ap.locator('[data-receive]').click();await ap.get_by_text('Entrega registrada. Se generó el aviso para el trabajador.',exact=True).wait_for();await ap.evaluate('window.__SICIP_RECEP_SHOW_FOLIO__()');await ap.locator('#sicip-recep-folio-input').fill(folio);await ap.evaluate('window.__SICIP_RECEP_FOLIO_SEARCH__()');await ap.locator('[data-receipt-status]').get_by_text('Entrega registrada:',exact=False).wait_for();assert await ap.locator('[data-receive]').count()==0;own=await api('/api/vacaciones/mi-pecv',own=True);assert next(x for x in own['solicitudes'] if x['uuid']==child['uuid'])['recibido']==1;print('PECV recibido por cámara/QR y folio manual desde Personal; acuse único visible para el trabajador.',flush=True)
  await p.locator('[data-notif-button]').click();await p.locator('[data-notifications]').get_by_text('Documento recibido en Personal',exact=True).wait_for();await p.locator('[data-notifications] [data-close]').click();
  await p.get_by_role('button',name='Mis Trámites',exact=False).first.click();await p.get_by_text('VACACIONES · PECV',exact=False).wait_for();
  if not await p.locator('[data-worker-pecv-nav]').is_visible():await p.locator('[data-sicip-solicitudes-btn]').click()
  await p.locator('[data-worker-pecv-nav]').click();await p.locator('[data-worker-pecv]').wait_for();child=await action(child,'CERTIFICAR',{'cumplimiento':True});await p.locator('[data-pecv-history]').get_by_text('CERTIFICADA',exact=True).wait_for(timeout=20000);await p.locator('[data-reprint="'+child['uuid']+'"]').click();frame=p.frame_locator('.coverage-print-dialog iframe');await frame.locator('.title').wait_for();assert 'pendiente' not in await frame.locator('.section').nth(1).inner_text();assert 'Administración de prueba' in await frame.locator('.signature').first.inner_text();await p.locator('.coverage-print-dialog [data-close]').click();f=p.locator('[data-worker-pecv]');await f.locator('[name=fecha0]').fill('2027-01-06');child=await action(child,'AUTORIZAR');await p.locator('[data-program-info]').get_by_text('Has utilizado 1 de 5',exact=False).wait_for(timeout=20000);assert await f.locator('[name=fecha0]').input_value()=='2027-01-06';updated=await api('/api/vacaciones/registros/'+parent['uuid']);assert updated['plan']['real']['jornadas']==15;assert updated['plan']['madre']==parent['plan']['madre'];print('Seguimiento propio, certificación real de Personal y descuento al autorizar; refresco conserva la fecha en captura.',flush=True)
  await p.set_viewport_size({'width':390,'height':844});assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');await p.screenshot(path='/workspace/sicip-env/pecv-trabajador-mobile.png');assert not errors,errors;await b.close();print('Móvil sin desborde ni errores JavaScript.',flush=True)
